      }

      .cat-collapsible {
        width: 100%;
        max-width: 400px;
        background: linear-gradient(135deg, rgba(255, 235, 240, 0.9), rgba(255, 202, 215, 0.8));
        border-radius: 20px;
        border: 2px solid rgba(255, 192, 203, 0.6);
