        position: relative;
        padding: 15px 20px;
        cursor: pointer;
        display: flex;
        align-items: center;
        justify-content: space-between;
        background: linear-gradient(135deg, rgba(255, 240, 245, 0.7), rgba(255, 228, 235, 0.6));
