        background: linear-gradient(135deg, rgba(255, 245, 248, 0.8), rgba(255, 235, 240, 0.7));
      }

      .cat-title {
        display: flex;
        align-items: center;
        gap: 10px;
        font-size: 16px;
        font-weight: bold;
        color: #8b4b7c;
        text-shadow: 0 1px 2px rgba(255, 255, 255, 0.8);
      }

      .cat-ears {
        position: relative;
        width: 24px;
        height: 20px;
        display: inline-block;
      }

      .cat-ears::before,
      .cat-ears::after {
        content: '';
        position: absolute;
        width: 8px;
        height: 12px;
