        border-radius: 50% 50% 0 0;
        border: 1px solid rgba(255, 182, 193, 0.8);
      }

      .cat-ears::before {
        left: 2px;
        transform: rotate(-20deg);
      }

      .cat-ears::after {
        right: 2px;
        transform: rotate(20deg);
      }

      .toggle-icon {
        width: 24px;
        height: 24px;
        border-radius: 50%;
        background: linear-gradient(135deg, #ffb6c1, #ff91a4);
        display: flex;
        align-items: center;
        justify-content: center;
        transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        box-shadow: 0 2px 6px rgba(255, 182, 193, 0.4);
        position: relative;
      }

      .toggle-icon::before {
        content: '▼';
        color: white;
        font-size: 12px;
        text-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
        transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
      }

      .cat-collapsible.expanded .toggle-icon {
        background: linear-gradient(135deg, #ff91a4, #ff7f9a);
        transform: scale(1.1);
      }

      .cat-collapsible.expanded .toggle-icon::before {
        transform: rotate(180deg);
      }

      .cat-content {
        max-height: 0;
        overflow: hidden;
        transition: max-height 0.4s cubic-bezier(0.4, 0, 0.2, 1);
        background: rgba(255, 248, 250, 0.6);
      }

      .cat-content-inner {
        padding: 20px;
        color: #7d4c7d;
        line-height: 1.6;
        font-size: 14px;
        border-top: 1px solid rgba(255, 192, 203, 0.2);
        position: relative;
        /* 保留换行符和空格，支持自动换行 */
        white-space: pre-wrap;
        /* 处理长单词换行 */
        word-wrap: break-word;
        word-break: break-word;
        /* 确保内容不会溢出容器 */
        overflow-wrap: break-word;
      }

      .cat-content-inner::before {
        content: '🐾';
        position: absolute;
        top: 10px;
        right: 15px;
        font-size: 12px;
        opacity: 0.6;
      }

      .cat-collapsible.expanded .cat-content {
        max-height: 500px;
      }

      /* 小猫爪印装饰 */
      .cat-collapsible::after {
        content: '';
        position: absolute;
        top: -5px;
        right: 20px;
        width: 20px;
        height: 20px;
        background: radial-gradient(circle at 30% 30%, rgba(255, 182, 193, 0.6) 2px, transparent 2px),
          radial-gradient(circle at 70% 30%, rgba(255, 182, 193, 0.6) 2px, transparent 2px),
          radial-gradient(circle at 50% 70%, rgba(255, 182, 193, 0.6) 3px, transparent 3px);
        background-size: 8px 8px;
        border-radius: 50%;
        opacity: 0.7;
      }

      /* 响应式设计 */
      @media (max-width: 480px) {
        .cat-collapsible {
          max-width: 100%;
          margin: 0 5px;
        }

        .cat-header {
          padding: 12px 15px;
        }

        .cat-title {
          font-size: 14px;
        }

        .cat-content-inner {
          padding: 15px;
          font-size: 13px;
        }
      }

      /* 动画增强 */
      @keyframes catPurr {
        0%,
        100% {
          transform: translateY(0);
        }
        50% {
          transform: translateY(-1px);
        }
      }

      .cat-collapsible:hover .cat-ears {
        animation: catPurr 1s ease-in-out infinite;
      }
    </style>
  </head>
  <body>
    <div class="cat-collapsible" id="catCollapsible">
      <div class="cat-header" onclick="toggleCollapsible()">
        <div class="cat-title">
          <span class="cat-ears"></span>
          小猫之神
        </div>
        <div class="toggle-icon"></div>
      </div>
      <div class="cat-content">
        <div class="cat-content-inner">$1</div>
      </div>
    </div>

    <script>
      function toggleCollapsible() {
        const collapsible = document.getElementById('catCollapsible');
        const content = collapsible.querySelector('.cat-content');

        if (collapsible.classList.contains('expanded')) {
          // 收起
          collapsible.classList.remove('expanded');
          content.style.maxHeight = '0';
        } else {
          // 展开
          collapsible.classList.add('expanded');
          // 动态计算内容高度
          const contentInner = content.querySelector('.cat-content-inner');
          const height = contentInner.scrollHeight + 40; // 加上padding
          content.style.maxHeight = height + 'px';
        }

        // 延迟更新iframe高度，等待动画完成
        setTimeout(updateIframeHeight, 400);
      }

      // 动态调整iframe高度的函数
      function updateIframeHeight() {
        const bodyHeight = document.body.scrollHeight;
        // 通知父页面调整iframe高度
        if (window.parent && window.parent !== window) {
          window.parent.postMessage(
            {
              type: 'resizeIframe',
              height: bodyHeight,
            },
            '*',
          );
        }
      }

      // 键盘支持
      document.addEventListener('keydown', function (event) {
        if (event.key === 'Enter' || event.key === ' ') {
          const activeElement = document.activeElement;
          if (activeElement && activeElement.classList.contains('cat-header')) {
            event.preventDefault();
            toggleCollapsible();
          }
        }
      });

      // 让header可以获取焦点以支持键盘操作
      document.querySelector('.cat-header').setAttribute('tabindex', '0');
    </script>
  </body>
