content => {
  const usernameRegex = /\|用户：(.*?)\|/;

  const usernameMatches = content.match(usernameRegex);
  let username = '用户';
  if (usernameMatches && usernameMatches.length > 1) {
    username = usernameMatches[1];
  }

  content = content.replace(usernameRegex, '');

  const deleteRegex = /\|delete\|[\s\S]*?\|\/delete\|/g;
  let result = content.replace(deleteRegex, '');

  let prev = null; // 'cat' | 'user' | 'friend' | 'model' | null
  const re = /[\n]*\|(小猫之神|用户|友人|模型|model)\|/g;

  return String(result).replace(re, (_, who) => {
    let roleName;
    if (who === '小猫之神') {
      roleName = 'soliumbra';
      prev = 'cat';
    } else if (who === '友人') {
      roleName = '友人';
      prev = 'friend';
    } else if (who === '模型' || who === 'model') {
      roleName = 'model';
      prev = 'model';
    } else {
      roleName = username;
      prev = 'user';
    }

    return `\n"}, {"role": "${roleName}", "content": "\n`;
  });
};

