        --mint: #86b8a9;
        --line: rgba(184, 111, 139, 0.22);
        --shadow: 0 12px 32px rgba(128, 66, 88, 0.16);
      }

      * { box-sizing: border-box; }
      [hidden] { display: none !important; }
      html, body { width: 100%; margin: 0; }
      body {
        padding: 6px;
        overflow: hidden;
        color: var(--ink);
        background: transparent;
        font-family: 'Microsoft YaHei UI', 'PingFang SC', system-ui, sans-serif;
      }
      button { font: inherit; }
      button:focus-visible { outline: 2px solid var(--berry); outline-offset: 3px; }

      .oracle-panel {
        position: relative;
        width: 100%;
        overflow: hidden;
        border: 1px solid rgba(255, 255, 255, 0.92);
        border-radius: 22px;
        background:
          radial-gradient(circle at 12px 12px, rgba(211, 125, 155, 0.12) 1.2px, transparent 1.3px) 0 0 / 24px 24px,
          linear-gradient(145deg, rgba(255, 250, 253, 0.98), rgba(255, 233, 241, 0.96));
        box-shadow: var(--shadow), inset 0 1px 0 #fff;
        isolation: isolate;
      }
      .oracle-panel::before {
        content: '';
        position: absolute;
        top: 0;
        right: 30px;
        width: 74px;
        height: 7px;
        border-radius: 0 0 8px 8px;
        background: linear-gradient(90deg, var(--blush), var(--rose));
        opacity: 0.8;
      }

      /* ─── Header ─── */
      .oracle-header {
        position: relative;
        z-index: 1;
        display: grid;
        grid-template-columns: auto minmax(0, 1fr) auto;
        align-items: center;
        gap: 12px;
        min-height: 78px;
        padding: 14px 16px 13px;
        border-bottom: 1px dashed rgba(197, 123, 150, 0.36);
        background: rgba(255, 255, 255, 0.36);
      }
      .cat-avatar {
        position: relative;
        width: 52px;
        height: 52px;
        flex: 0 0 auto;
        border: 1px solid rgba(199, 116, 146, 0.35);
        border-radius: 48% 48% 45% 45%;
        overflow: hidden;
        background: radial-gradient(circle at 50% 44%, #fff 0 25%, #ffe4ed 74%, #f5b9cb 100%);
        box-shadow: 0 6px 14px rgba(165, 86, 114, 0.2), inset 0 1px 0 #fff;
        isolation: isolate;
      }
      .cat-avatar::before {
        content: '';
        position: absolute;
        inset: 2px;
        z-index: 2;
        border: 1px solid rgba(255, 255, 255, 0.72);
        border-radius: inherit;
        pointer-events: none;
      }
      .cat-avatar::after {
        content: '';
        position: absolute;
        inset: 0;
        z-index: 1;
        background: linear-gradient(145deg, rgba(255, 255, 255, 0.28), transparent 45%, rgba(228, 128, 161, 0.12));
        pointer-events: none;
      }
      .cat-avatar img {
        width: 100%;
        height: 100%;
        display: block;
        object-fit: cover;
        object-position: 50% 48%;
        filter: saturate(0.82) contrast(0.95) brightness(1.06);
        mix-blend-mode: multiply;
        transform: scale(1.13);
        -webkit-mask-image: radial-gradient(ellipse 68% 72% at 51% 49%, #000 54%, rgba(0, 0, 0, 0.92) 70%, transparent 100%);
        mask-image: radial-gradient(ellipse 68% 72% at 51% 49%, #000 54%, rgba(0, 0, 0, 0.92) 70%, transparent 100%);
      }

      .title-block { min-width: 0; }
      .eyebrow {
        margin-bottom: 2px;
        color: var(--rose);
        font-size: 9px;
        font-weight: 800;
        letter-spacing: 0.16em;
        text-transform: uppercase;
      }
      h1 {
        margin: 0;
        color: var(--berry);
        font-family: 'CutieFont', 'Microsoft YaHei UI', sans-serif;
        font-size: clamp(19px, 4vw, 24px);
        font-weight: 700;
        line-height: 1.08;
        letter-spacing: 0.03em;
      }
      .subtitle {
        margin: 4px 0 0;
        overflow: hidden;
        color: var(--muted);
        font-size: 10px;
        line-height: 1.35;
        text-overflow: ellipsis;
        white-space: nowrap;
      }

      .mode-toggle {
        min-width: 116px;
        display: grid;
        grid-template-columns: minmax(0, 1fr) 40px;
        align-items: center;
        gap: 9px;
        padding: 7px 8px 7px 10px;
        border: 1px solid var(--line);
        border-radius: 12px;
        color: var(--muted);
        background: rgba(255, 255, 255, 0.62);
        cursor: pointer;
        text-align: left;
        transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
      }
      .mode-toggle:hover { border-color: rgba(184, 99, 132, 0.42); background: rgba(255, 255, 255, 0.86); }
      .mode-toggle:active { transform: scale(0.98); }
      .mode-copy { display: grid; gap: 1px; }
      .mode-copy strong { color: var(--ink); font-size: 11px; font-weight: 750; }
      .mode-copy small { color: var(--muted); font-size: 8px; white-space: nowrap; }
      .switch-track {
        width: 40px;
        height: 20px;
        display: block;
        padding: 2px;
        border: 1px solid rgba(174, 124, 143, 0.3);
        border-radius: 999px;
        background: #eadde2;
        transition: background 180ms ease, border-color 180ms ease;
      }
      .switch-knob {
        width: 14px;
        height: 14px;
        display: block;
        border-radius: 50%;
        background: #fff;
        box-shadow: 0 2px 5px rgba(99, 57, 72, 0.2);
        transition: transform 200ms cubic-bezier(0.2, 0.8, 0.2, 1), background 180ms ease;
      }
      .mode-toggle[data-mode='send'] .switch-track { border-color: var(--rose); background: var(--blush); }
      .mode-toggle[data-mode='replace'] .switch-track { border-color: rgba(184, 111, 139, 0.42); background: #eadde2; }
      .mode-toggle[data-mode='append'] .switch-track { border-color: var(--mint); background: rgba(134, 184, 169, 0.38); }
      .mode-toggle[data-mode='send'] .switch-knob { background: #fffafb; transform: translateX(20px); }
      .mode-toggle[data-mode='replace'] .switch-knob { transform: translateX(10px); }
      .mode-toggle[data-mode='append'] .switch-knob { transform: translateX(0); }

      /* ─── Comment Region (小猫之神的留言) ─── */
      .comment-region {
        position: relative;
        z-index: 1;
        padding: 12px 14px 2px;
      }
      .comment-card {
        position: relative;
        padding: 10px 13px 10px 14px;
        border: 1px solid rgba(207, 120, 149, 0.28);
        border-radius: 14px;
        background: linear-gradient(135deg, rgba(255, 255, 255, 0.88), rgba(255, 240, 246, 0.82));
        box-shadow: 0 3px 10px rgba(140, 74, 98, 0.06), inset 0 1px 0 #fff;
        animation: option-arrive 280ms cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
      }
      .comment-card::before {
        content: '';
        position: absolute;
        top: 9px;
        bottom: 9px;
        left: 0;
        width: 3.5px;
        border-radius: 0 4px 4px 0;
        background: linear-gradient(180deg, var(--blush), var(--rose));
      }
      .comment-head {
        display: flex;
        align-items: center;
        gap: 6px;
        margin-bottom: 4px;
        color: var(--berry);
        font-size: 11px;
        font-weight: 750;
        letter-spacing: 0.02em;
      }
      .comment-badge {
        display: inline-flex;
        align-items: center;
        padding: 1px 6px;
        border-radius: 999px;
        background: rgba(246, 184, 203, 0.35);
        color: var(--rose);
        font-size: 9px;
        font-weight: 700;
      }
      .comment-body {
        color: var(--ink);
        font-size: 12.5px;
        line-height: 1.56;
        white-space: pre-wrap;
        overflow-wrap: anywhere;
      }

      /* ─── Option Region (回应选项) ─── */
      .option-region { position: relative; z-index: 1; padding: 12px 14px 10px; }
      .option-region::before {
        content: '';
        position: absolute;
        top: 22px;
        bottom: 22px;
        left: 35px;
        width: 1px;
        background: repeating-linear-gradient(to bottom, rgba(195, 113, 143, 0.38) 0 4px, transparent 4px 8px);
        pointer-events: none;
      }
      .option-list {
        max-height: min(430px, 68vh);
        display: grid;
        gap: 8px;
        margin: 0;
        padding: 0 3px 0 0;
        overflow-x: hidden;
        overflow-y: auto;
        list-style: none;
        scrollbar-color: rgba(195, 113, 143, 0.32) transparent;
        scrollbar-width: thin;
      }
      .option-list::-webkit-scrollbar { width: 5px; }
      .option-list::-webkit-scrollbar-thumb { border-radius: 999px; background: rgba(195, 113, 143, 0.32); }

      .option-btn {
        position: relative;
        width: 100%;
        min-height: 52px;
        display: grid;
        grid-template-columns: 32px minmax(0, 1fr) 24px;
        align-items: center;
        gap: 9px;
        padding: 8px 10px 8px 7px;
        overflow: hidden;
        border: 1px solid rgba(190, 122, 147, 0.2);
        border-radius: 13px;
        color: var(--ink);
        background: rgba(255, 255, 255, 0.72);
        box-shadow: 0 2px 8px rgba(120, 73, 90, 0.06);
        cursor: pointer;
        text-align: left;
        opacity: 0;
        transform: translateY(6px);
        animation: option-arrive 320ms cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
        animation-delay: var(--delay, 0ms);
        transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease, transform 160ms ease;
      }
      .option-btn::after {
        content: '';
        position: absolute;
        inset: 0 auto 0 0;
        width: 3px;
        border-radius: 13px 0 0 13px;
        background: var(--blush);
        transition: width 160ms ease, background 160ms ease;
      }
      .option-btn:hover {
        border-color: rgba(190, 107, 138, 0.42);
        background: rgba(255, 255, 255, 0.96);
        box-shadow: 0 7px 16px rgba(130, 70, 92, 0.12);
        transform: translateY(-1px);
      }
      .option-btn:hover::after,
      .option-btn.is-selected::after { width: 5px; background: var(--rose); }
      .option-btn:active { transform: translateY(0) scale(0.99); }
      .option-btn.is-selected { border-color: rgba(190, 107, 138, 0.52); background: #fff; }
      .option-index {
        position: relative;
        z-index: 1;
        width: 29px;
        height: 29px;
        display: grid;
        place-items: center;
        border: 1px solid rgba(197, 119, 148, 0.28);
        border-radius: 10px 10px 10px 4px;
        color: var(--rose);
        background: linear-gradient(145deg, #fff, #ffeaf1);
        font: 700 9px/1 ui-monospace, 'SFMono-Regular', Consolas, monospace;
        box-shadow: inset 0 1px 0 #fff;
      }
      .option-text {
        min-width: 0;
        font-size: 13px;
        line-height: 1.52;
        white-space: pre-wrap;
        overflow-wrap: anywhere;
      }
      .option-paw {
        color: var(--blush);
        font-size: 15px;
        text-align: center;
        opacity: 0.7;
        transform: rotate(-14deg);
        transition: color 160ms ease, opacity 160ms ease, transform 160ms ease;
      }
      .option-btn:hover .option-paw,
      .option-btn.is-selected .option-paw { color: var(--rose); opacity: 1; transform: rotate(0deg) scale(1.08); }

      /* ─── Summary Region (剧情小总结) ─── */
      .summary-region {
        position: relative;
        z-index: 1;
        padding: 4px 14px 10px;
      }
      . comment-region + .summary-region,
      .oracle-header + .summary-region:not([hidden]) {
        padding-top: 12px;
      }
      .summary-details {
        border: 1px dashed rgba(195, 118, 146, 0.38);
        border-radius: 14px;
        background: rgba(255, 255, 255, 0.56);
        overflow: hidden;
        transition: background 180ms ease, border-color 180ms ease, box-shadow 180ms ease;
      }
      .summary-details[open] {
        border-style: solid;
        border-color: rgba(195, 118, 146, 0.34);
        background: rgba(255, 255, 255, 0.84);
        box-shadow: 0 4px 12px rgba(130, 70, 92, 0.06);
      }
      .summary-trigger {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 8px;
        padding: 9px 13px;
        color: var(--berry);
        font-size: 11.5px;
        font-weight: 750;
        cursor: pointer;
        user-select: none;
        list-style: none;
        transition: background 150ms ease;
      }
      .summary-trigger::-webkit-details-marker { display: none; }
      .summary-trigger:hover { background: rgba(255, 232, 240, 0.45); }
      .summary-trigger-left {
        display: flex;
        align-items: center;
        gap: 7px;
      }
      .summary-icon {
        display: inline-grid;
        place-items: center;
        width: 20px;
        height: 20px;
        border-radius: 6px;
        background: linear-gradient(145deg, #fff, #ffe4ed);
        border: 1px solid rgba(197, 119, 148, 0.28);
        color: var(--rose);
        font-size: 11px;
      }
      .summary-chevron {
        color: var(--muted);
        font-size: 10px;
        transition: transform 200ms cubic-bezier(0.2, 0.8, 0.2, 1), color 160ms ease;
      }
      .summary-details[open] .summary-chevron {
        color: var(--rose);
        transform: rotate(180deg);
      }
      .summary-content {
        padding: 10px 14px 12px;
        border-top: 1px dashed rgba(197, 123, 150, 0.26);
        color: var(--ink);
        font-size: 12px;
        line-height: 1.62;
        white-space: pre-wrap;
        overflow-wrap: anywhere;
      }

      /* ─── Footer ─── */
      .oracle-footer {
        position: relative;
        z-index: 1;
        min-height: 34px;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 12px;
        padding: 7px 16px 9px;
        border-top: 1px dashed rgba(197, 123, 150, 0.22);
        color: var(--muted);
        font-size: 9px;
      }
      .oracle-footer span:first-child::before { content: '✦'; margin-right: 5px; color: var(--rose); }
      .status { overflow: hidden; text-align: right; text-overflow: ellipsis; white-space: nowrap; }
      .status.is-error { color: #b64f63; }

      @keyframes option-arrive { to { opacity: 1; transform: translateY(0); } }

      @media (max-width: 520px) {
        body { padding: 3px; }
        .oracle-panel { border-radius: 18px; }
        .oracle-header { grid-template-columns: auto minmax(0, 1fr); gap: 10px; padding: 13px 12px 11px; }
        .cat-avatar { width: 48px; height: 48px; }
        .mode-toggle { grid-column: 1 / -1; width: 100%; min-height: 42px; }
        .mode-copy { display: flex; align-items: baseline; gap: 7px; }
        .comment-region { padding: 10px 10px 2px; }
        .option-region { padding: 10px; }
        .option-region::before { left: 29px; }
        .option-btn { grid-template-columns: 30px minmax(0, 1fr) 18px; gap: 7px; min-height: 50px; border-radius: 11px; }
        .option-text { font-size: 12px; }
        .summary-region { padding: 4px 10px 10px; }
        .oracle-footer { padding-inline: 12px; }
      }

      @media (prefers-reduced-motion: reduce) {
        *, *::before, *::after {
          scroll-behavior: auto !important;
          animation-duration: 0.01ms !important;
          animation-delay: 0ms !important;
          transition-duration: 0.01ms !important;
        }
      }
    </style>
  </head>
  <body>
    <template id="raw-data">$1</template>

    <main class="oracle-panel" aria-labelledby="oracle-title">
      <header class="oracle-header">
        <div class="cat-avatar" aria-hidden="true"><img src="https://files.catbox.moe/y9gi00.png" alt="" /></div>
        <div class="title-block">
          <div class="eyebrow">Cat oracle · 小猫之神</div>
          <h1 id="oracle-title">请选择回应喵</h1>
          <p class="subtitle" id="oracleSubtitle" hidden></p>
        </div>
        <button class="mode-toggle" id="directSendToggle" type="button" data-mode="send" aria-label="当前模式：直接发送；点击切换">
          <span class="mode-copy">
            <strong id="modeTitle">直接发送</strong>
            <small id="modeHint">点选后立即发出</small>
          </span>
          <span class="switch-track" aria-hidden="true"><span class="switch-knob"></span></span>
        </button>
      </header>

      <!-- 1. 小猫之神的留言 (<comment>) -->
      <section class="comment-region" id="commentRegion" aria-label="小猫之神的留言" hidden>
        <div class="comment-card">
          <div class="comment-head">
            <span>🐾 小猫之神的悄悄话</span>
            <span class="comment-badge">Nya~</span>
          </div>
          <div class="comment-body" id="commentBody"></div>
        </div>
      </section>

      <!-- 2. 回应选项 (<options>) -->
      <section class="option-region" id="optionRegion" aria-label="回应选项" hidden>
        <ol class="option-list" id="listRoot"></ol>
      </section>

      <!-- 3. 剧情小总结 (<summary>) -->
      <section class="summary-region" id="summaryRegion" aria-label="剧情摘要" hidden>
        <details class="summary-details" id="summaryDetails">
          <summary class="summary-trigger">
            <span class="summary-trigger-left">
              <span class="summary-icon" aria-hidden="true">📖</span>
              <span id="summaryTitleText">剧情小总结</span>
            </span>
            <span class="summary-chevron" aria-hidden="true">▼</span>
          </summary>
          <div class="summary-content" id="summaryBody"></div>
        </details>
      </section>

      <footer class="oracle-footer">
        <span id="optionCount">正在读取神谕…</span>
        <span class="status" id="statusText" role="status" aria-live="polite">选一条就好</span>
      </footer>
    </main>

    <script>
      (() => {
        'use strict';

        const rawData = document.getElementById('raw-data');
        const oracleTitle = document.getElementById('oracle-title');
        const oracleSubtitle = document.getElementById('oracleSubtitle');
        const toggle = document.getElementById('directSendToggle');
        const modeTitle = document.getElementById('modeTitle');
        const modeHint = document.getElementById('modeHint');

        const commentRegion = document.getElementById('commentRegion');
        const commentBody = document.getElementById('commentBody');
        const optionRegion = document.getElementById('optionRegion');
        const listRoot = document.getElementById('listRoot');
        const summaryRegion = document.getElementById('summaryRegion');
        const summaryDetails = document.getElementById('summaryDetails');
        const summaryBody = document.getElementById('summaryBody');

        const optionCount = document.getElementById('optionCount');
        const statusText = document.getElementById('statusText');
        const panel = document.querySelector('.oracle-panel');

        const optionModes = ['send', 'replace', 'append'];
        let optionMode = 'send';
        let selectedButton = null;
        let resizeFrame = 0;
        let hasExtraSections = false;

        function getSillyTavern() {
          try {
            return window.top?.SillyTavern || window.parent?.SillyTavern || null;
          } catch (error) {
            console.warn('[Cat Oracle] SillyTavern context is unavailable', error);
            return null;
          }
        }

        function setStatus(message, isError = false) {
          statusText.textContent = message;
          statusText.classList.toggle('is-error', isError);
        }

        function updateHeight() {
          resizeFrame = 0;
          if (window.parent && window.parent !== window) {
            window.parent.postMessage({ type: 'resizeIframe', height: document.body.scrollHeight }, '*');
          }
        }

        function scheduleHeightUpdate() {
          if (resizeFrame) cancelAnimationFrame(resizeFrame);
          resizeFrame = requestAnimationFrame(updateHeight);
        }

        function cleanTextFromHtml(html) {
          const template = document.createElement('template');
          template.innerHTML = html;
          template.content.querySelectorAll('script, style').forEach(el => el.remove());
          template.content.querySelectorAll('br').forEach(el => el.replaceWith('\n'));
          return (template.content.textContent || '').trim();
        }

        function looseOptionLinesFromHtml(html) {
          const template = document.createElement('template');
          template.innerHTML = html;
          template.content.querySelectorAll('script, style').forEach(element => element.remove());
          template.content.querySelectorAll('br').forEach(element => element.replaceWith('\n'));
          template.content.querySelectorAll('p, div, li').forEach(element => element.append('\n'));
          return (template.content.textContent || '')
            .split(/\r?\n/)
            .map(line => line
              .replace(/^\s*(?:[-*•]\s+|\d{1,3}[.)、]\s*)/, '')
              .trim())
            .filter(Boolean);
        }

        function extractTagBlocks(source, tagName) {
          const results = [];
          const regex = new RegExp(`<${tagName}\\b[^>]*>([\\s\\S]*?)<\\/${tagName}>`, 'gi');
          let match;
          while ((match = regex.exec(source)) !== null) {
            const cleaned = cleanTextFromHtml(match[1]);
            if (cleaned) results.push(cleaned);
          }
          return results;
        }

        function parseOptionsEntries(optionsRawList) {
          const entries = [];
          for (const optionsBody of optionsRawList) {
            const optionPattern = /<option\b[^>]*>([\s\S]*?)<\/option>/gi;
            let cursor = 0;
            let match;
            while ((match = optionPattern.exec(optionsBody)) !== null) {
              entries.push(...looseOptionLinesFromHtml(optionsBody.slice(cursor, match.index)));
              const text = cleanTextFromHtml(match[1]);
              if (text) entries.push(text);
              cursor = optionPattern.lastIndex;
            }
            entries.push(...looseOptionLinesFromHtml(optionsBody.slice(cursor)));
          }
          return entries;
        }

        function parseAndRender() {
          const source = String(rawData.innerHTML || '').trim();

          // 1. 提取 <comment>
          const comments = extractTagBlocks(source, 'comment');
          const hasComment = comments.length > 0;
          if (hasComment) {
            commentBody.textContent = comments.join('\n\n');
            commentRegion.hidden = false;
          } else {
            commentRegion.hidden = true;
          }

          // 2. 提取 <summary>
          const summaries = extractTagBlocks(source, 'summary');
          const hasSummary = summaries.length > 0;
          if (hasSummary) {
            summaryBody.textContent = summaries.join('\n\n');
            summaryRegion.hidden = false;
          } else {
            summaryRegion.hidden = true;
          }

          // 3. 提取 <options>
          const rawOptionsMatches = [];
          const optRegex = /<options\b[^>]*>([\s\S]*?)<\/options>/gi;
          let optMatch;
          while ((optMatch = optRegex.exec(source)) !== null) {
            rawOptionsMatches.push(optMatch[1]);
          }
          // 兼容直接传入裸选项内容的情况
          if (!rawOptionsMatches.length && !hasComment && !hasSummary && source) {
            rawOptionsMatches.push(source);
          }

          const entries = parseOptionsEntries(rawOptionsMatches);
          const hasOptions = entries.length > 0;
          hasExtraSections = hasComment || hasSummary;

          if (hasOptions) {
            optionRegion.hidden = false;
            toggle.hidden = false;
            oracleTitle.textContent = '请选择回应喵';
            oracleSubtitle.hidden = true;

            const fragment = document.createDocumentFragment();
            entries.forEach((text, index) => {
              const item = document.createElement('li');
              const button = document.createElement('button');
              const number = document.createElement('span');
              const copy = document.createElement('span');
              const paw = document.createElement('span');

              button.type = 'button';
              button.className = 'option-btn';
              button.style.setProperty('--delay', `${Math.min(index * 42, 252)}ms`);
              button.setAttribute('aria-label', `选择回应 ${index + 1}：${text}`);
              number.className = 'option-index';
              number.textContent = String(index + 1).padStart(2, '0');
              number.setAttribute('aria-hidden', 'true');
              copy.className = 'option-text';
              copy.textContent = text;
              paw.className = 'option-paw';
              paw.textContent = '♥';
              paw.setAttribute('aria-hidden', 'true');
              button.append(number, copy, paw);
              button.addEventListener('click', () => handleSelect(text, button));
              item.appendChild(button);
              fragment.appendChild(item);
            });
            listRoot.replaceChildren(fragment);
          } else {
            optionRegion.hidden = true;
            toggle.hidden = true;
            oracleTitle.textContent = hasComment && !hasSummary ? '小猫之神的悄悄话喵' : '神谕手札喵';
            oracleSubtitle.textContent = '本喵为你记下这一刻的轨迹啦';
            oracleSubtitle.hidden = false;
          }

          // 当只有 <summary>（没有 <options>）时，默认自动展开摘要
          if (hasSummary) {
            summaryDetails.open = !hasOptions;
          }

          // 4. 更新底部状态栏统计信息
          const parts = [];
          if (hasOptions) parts.push(`共 ${entries.length} 条回应`);
          if (hasComment) parts.push('猫神留言');
          if (hasSummary) parts.push('剧情摘要');
          optionCount.textContent = parts.length ? parts.join(' · ') : '神谕已送达';

          if (hasOptions) {
            setStatus('选一条就好喵');
          } else if (hasSummary) {
            setStatus('点击摘要标题可折叠/展开');
          } else {
            setStatus('喵呼呼~');
          }

          scheduleHeightUpdate();
        }

        function updateToggleUi() {
          const modeCopy = {
            send: ['直接发送', '点选后立即发出'],
            replace: ['仅填入', '覆盖输入框现有内容'],
            append: ['增量填入', '追加到输入框现有内容'],
          }[optionMode];
          toggle.dataset.mode = optionMode;
          toggle.setAttribute('aria-label', `当前模式：${modeCopy[0]}；点击切换`);
          modeTitle.textContent = modeCopy[0];
          modeHint.textContent = modeCopy[1];
        }

        function initToggle() {
          try {
            const st = getSillyTavern();
            const context = st?.getContext?.();
            const settings = context?.extensionSettings?.Astro;
            if (optionModes.includes(settings?.optionMode)) {
              optionMode = settings.optionMode;
            } else if (typeof settings?.directSend === 'boolean') {
              optionMode = settings.directSend ? 'send' : 'append';
            }
          } catch (error) {
            console.warn('[Cat Oracle] Failed to read direct-send setting', error);
          }

          updateToggleUi();
          toggle.addEventListener('click', () => {
            optionMode = optionModes[(optionModes.indexOf(optionMode) + 1) % optionModes.length];
            updateToggleUi();
            setStatus(`已切换为${modeTitle.textContent}`);

            try {
              const st = getSillyTavern();
              const context = st?.getContext?.();
              if (!context) return;
              context.extensionSettings ||= {};
              context.extensionSettings.Astro ||= {};
              context.extensionSettings.Astro.optionMode = optionMode;
              context.extensionSettings.Astro.directSend = optionMode === 'send';
              if (typeof st?.saveSettingsDebounced === 'function') st.saveSettingsDebounced();
              else context.saveSettingsDebounced?.();
            } catch (error) {
              console.error('[Cat Oracle] Failed to save direct-send setting', error);
              setStatus('模式已切换，但未能保存设置', true);
            }
            scheduleHeightUpdate();
          });
        }

        function removeOwnIframe() {
          try {
            const frames = window.parent?.document?.querySelectorAll('iframe') || [];
            for (const frame of frames) {
              if (frame.contentWindow === window) {
                frame.remove();
                break;
              }
            }
          } catch (error) {
            console.warn('[Cat Oracle] Failed to close option frame', error);
          }
        }

        function handleSelect(text, button) {
          try {
            const parentDocument = window.parent?.document;
            const textarea = parentDocument?.getElementById('send_textarea');
            if (!textarea) {
              setStatus('未找到酒馆输入框', true);
              return;
            }

            selectedButton?.classList.remove('is-selected');
            selectedButton = button;
            selectedButton.classList.add('is-selected');

            const currentValue = String(textarea.value || '');
            const separator = currentValue && !/\r?\n$/.test(currentValue) ? '\n' : '';
            const nextValue = optionMode === 'append' ? `${currentValue}${separator}${text}` : text;
            const parentWindow = window.parent;
            const textareaPrototype = parentWindow?.HTMLTextAreaElement?.prototype || HTMLTextAreaElement.prototype;
            const valueSetter = Object.getOwnPropertyDescriptor(textareaPrototype, 'value')?.set;
            if (valueSetter) valueSetter.call(textarea, nextValue);
            else textarea.value = nextValue;
            const ParentEvent = parentWindow?.Event || Event;
            textarea.dispatchEvent(new ParentEvent('input', { bubbles: true }));
            textarea.dispatchEvent(new ParentEvent('change', { bubbles: true }));
            textarea.focus();
            textarea.setSelectionRange?.(nextValue.length, nextValue.length);

            if (optionMode !== 'send') {
              setStatus(optionMode === 'append' ? '已追加到酒馆输入框' : '已填入酒馆输入框');
              return;
            }

            const st = getSillyTavern();
            const context = st?.getContext?.();
            if (typeof context?.generate === 'function') context.generate();
            else {
              const sendButton = parentDocument.getElementById('send_but');
              if (!sendButton) throw new Error('Send button is unavailable');
              sendButton.click();
            }

            // 如果卡片里还有 <comment> 或 <summary>，只收起选项区保留手札；若只有选项则移除整个 iframe
            if (hasExtraSections) {
              optionRegion.hidden = true;
              toggle.hidden = true;
              oracleTitle.textContent = '神谕手札喵';
              setStatus('已发送回应喵');
              scheduleHeightUpdate();
            } else {
              removeOwnIframe();
            }
          } catch (error) {
            console.error('[Cat Oracle] Failed to apply option', error);
            setStatus('未能应用这条回应，请检查控制台', true);
          }
        }

        window.addEventListener('DOMContentLoaded', () => {
          parseAndRender();
          initToggle();
          summaryDetails.addEventListener('toggle', scheduleHeightUpdate);
          scheduleHeightUpdate();
          window.addEventListener('resize', scheduleHeightUpdate);
          if ('ResizeObserver' in window) new ResizeObserver(scheduleHeightUpdate).observe(panel);
          document.fonts?.ready?.then(scheduleHeightUpdate);
        });
      })();
    </script>
  </body>
</html>
